class OverlappingVirtualMembership(unittest.TestCase):
    """Coverage for overlapping virtual membership across unrelated
    and subclass-related abstract union members."""

    def test_unrelated_abcs_pep604_ambiguous(self):
        """PEP 604: two unrelated ABCs raise RuntimeError on dispatch."""

        class Shape(ABC):
            pass

        class Style(ABC):
            pass

        class Document:
            pass

        @functools.singledispatch
        def handler(x):
            return "default"

        @handler.register(Shape | Style)
        def union_handler(x):
            return "union"

        doc = Document()
        self.assertEqual(handler(doc), "default")

        Shape.register(Document)
        Style.register(Document)

        with self.assertRaises(RuntimeError) as ctx:
            handler(doc)
        self.assertEqual(
            str(ctx.exception),
            f"Ambiguous dispatch: {Shape} or {Style}"
        )

